1 | /**
2 |  * Tool Registry
3 |  *
4 |  * 工具注册中心，负责管理所有可用的工具
5 |  *
6 |  * @example
7 |  * ```ts
8 |  * import { ToolRegistry } from './index';
9 |  *
10 |  * // 获取所有工具
11 |  * const tools = ToolRegistry.getAll();
12 |  *
13 |  * // 根据名称获取工具
14 |  * const bashTool = ToolRegistry.get('bash');
15 |  *
16 |  * // 执行工具
17 |  * const result = await bashTool.execute({ command: 'ls' });
18 |  * ```
19 |  */
20 | 
21 | import { ToolRegistry } from './registry';
22 | import BashTool from './bash';
23 | import GlobTool from './glob';
24 | import { ReadFileTool } from './file';
25 | import { WriteFileTool } from './file';
26 | import GrepTool from './grep';
27 | import { SurgicalEditTool } from './surgical';
28 | import { BatchReplaceTool } from './batch-replace';
29 | import { TodoReadTool } from './todo';
30 | import { TodoWriteTool } from './todo';
31 | import { initializeMcp } from '../mcp/index';
32 | import { WebSearchTool } from './web-search';
33 | import { SkillTool, initializeSkills } from '../skills';
34 | import TaskTool from './task';
35 | import CompleteTaskTool from './complete-task';
36 | 
37 | // =============================================================================
38 | // Tool Registry
39 | // =============================================================================
40 | 
41 | export { ToolRegistry } from './registry';
42 | 
43 | // =============================================================================
44 | // Default Tools Registration
45 | // =============================================================================
46 | 
47 | /**
48 |  * 初始化并注册所有默认工具
49 |  *
50 |  * 在应用启动时调用此函数
51 |  */
52 | export function registerDefaultTools(): void {
53 | 
54 |     ToolRegistry.register([
55 |         new BashTool(),
56 |         new GlobTool(),
57 |         new GrepTool(),
58 |         new ReadFileTool(),
59 |         new WriteFileTool(),
60 |         new SurgicalEditTool(),
61 |         new BatchReplaceTool(),
62 |         new TodoReadTool(),
63 |         new TodoWriteTool(),
64 |         new WebSearchTool(),
65 |         new SkillTool(),
66 |         new TaskTool(),
67 |         new CompleteTaskTool()
68 |     ]);
69 | }
70 | 
71 | /**
72 |  * 初始化并注册所有工具（包括 MCP 服务器工具）
73 |  *
74 |  * 在应用启动时调用此函数，异步加载 MCP 服务器
75 |  *
76 |  * @param configPath - MCP 配置文件路径（可选）
77 |  * @returns MCP 管理器实例
78 |  *
79 |  * @example
80 |  * ```ts
81 |  * import { registerDefaultToolsAsync } from './tool';
82 |  *
83 |  * // 使用默认配置路径
84 |  * await registerDefaultToolsAsync();
85 |  *
86 |  * // 或指定配置文件路径
87 |  * await registerDefaultToolsAsync('./my-mcp-config.json');
88 |  * ```
89 |  */
90 | export async function registerDefaultToolsAsync(configPath?: string) {
91 |     // 初始化技能加载器（在注册 SkillTool 之前）
92 |     try {
93 |         await initializeSkills();
94 |     } catch (error) {
95 |         console.warn('[Skills] Failed to initialize skills:', error);
96 |     }
97 | 
98 |     // 注册内置工具
99 |     registerDefaultTools();
100 | 
101 |     // 初始化 MCP 服务器（如果配置文件存在）
102 |     try {
103 |         const manager = await initializeMcp(configPath);
104 |         const servers = manager.getConnectedServers();
105 |         const totalTools = manager.getTotalToolsCount();
106 | 
107 |         if (servers.length > 0) {
108 |             console.log(`[MCP] Loaded ${totalTools} tools from ${servers.length} server(s)`);
109 |         }
110 | 
111 |         return manager;
112 |     } catch (error) {
113 |         // MCP 加载失败不应该阻止应用启动
114 |         if (error instanceof Error && !error.message.includes('not found')) {
115 |             console.warn('[MCP] Failed to load MCP servers:', error.message);
116 |         }
117 |         return null;
118 |     }
119 | }
120 | 
121 | // =============================================================================
122 | // Exports
123 | // =============================================================================
124 | 
125 | export { BaseTool } from './base';
126 | export { default as BashTool } from './bash';
127 | export { getBashParser } from './bash-parser';
128 | export type { CommandInfo, SecurityIssue, ParseResult } from './bash-parser';
129 | export { BatchReplaceTool } from './batch-replace';
130 | export { default as TaskTool } from './task';
131 | 
132 | export { initializeSkills, getSkillLoader } from '../skills/loader';
133 | export type { Skill, SkillMetadata, SkillLoaderOptions } from '../skills/types';
134 | export { default as CompleteTaskTool } from './complete-task';
