--- FILE: src/tool/registry.ts ---
Range: 1 - 295

1 | import { BaseTool } from "./base";
2 | 
3 | /**
4 |  * 工具注册表类
5 |  *
6 |  * 单例模式，管理所有可用的工具
7 |  */
8 | export class ToolRegistry {
9 |     /** 已注册的工具映射 */
10 |     private static tools: Map<string, BaseTool<any>> = new Map();
11 |     private static context: { sessionId?: string; sessionPath?: string; allowedTools?: string[] } = {};
12 | 
13 |     /** 私有构造函数，防止外部实例化 */
14 |     private constructor() {}
15 | 
16 |     /**
17 |      * 注册工具
18 |      *
19 |      * 支持单个工具或工具数组
20 |      *
21 |      * @param tool - 工具实例或工具数组
22 |      * @throws 如果工具名称已存在
23 |      *
24 |      * @example
25 |      * ```ts
26 |      * // 注册单个工具
27 |      * ToolRegistry.register(new BashTool());
28 |      *
29 |      * // 批量注册工具
30 |      * ToolRegistry.register([new BashTool(), new GrepTool()]);
31 |      * ```
32 |      */
33 |     static register<T extends BaseTool<any>>(tool: T | T[]): void {
34 |         const tools = Array.isArray(tool) ? tool : [tool];
35 |         for (const t of tools) {
36 |             if (this.tools.has(t.name)) {
37 |                 throw new Error(`Tool "${t.name}" is already registered`);
38 |             }
39 |             this.tools.set(t.name, t);
40 |         }
41 |     }
42 | 
43 |     /**
44 |      * 注销工具
45 |      *
46 |      * @param name - 工具名称
47 |      * @returns 是否成功注销
48 |      */
49 |     static unregister(name: string): boolean {
50 |         return this.tools.delete(name);
51 |     }
52 | 
53 |     /**
54 |      * 根据名称获取工具
55 |      *
56 |      * @param name - 工具名称
57 |      * @returns 工具实例，如果不存在则返回 undefined
58 |      */
59 |     static get<T extends BaseTool<any> = BaseTool<any>>(name: string): T | undefined {
60 |         return this.tools.get(name) as T | undefined;
61 |     }
62 | 
63 |     /**
64 |      * 获取所有已注册的工具
65 |      *
66 |      * @returns 工具实例数组
67 |      */
68 |     static getAll(): BaseTool<any>[] {
69 |         return Array.from(this.tools.values());
70 |     }
71 | 
72 |     /**
73 |      * 获取所有工具的名称
74 |      *
75 |      * @returns 工具名称数组
76 |      */
77 |     static getNames(): string[] {
78 |         return Array.from(this.tools.keys());
79 |     }
80 | 
81 |     /**
82 |      * 检查工具是否已注册
83 |      *
84 |      * @param name - 工具名称
85 |      * @returns 是否已注册
86 |      */
87 |     static has(name: string): boolean {
88 |         return this.tools.has(name);
89 |     }
90 | 
91 |     /**
92 |      * 获取已注册工具的数量
93 |      *
94 |      * @returns 工具数量
95 |      */
96 |     static get size(): number {
97 |         return this.tools.size;
98 |     }
99 | 
100 |     /**
101 |      * 清空所有已注册的工具
102 |      *
103 |      * @warning 这通常只在测试中使用
104 |      */
105 |     static clear(): void {
106 |         this.tools.clear();
107 |     }
108 | 
109 |     static setContext(context: { sessionId?: string; sessionPath?: string; allowedTools?: string[] }): void {
110 |         const next = { ...this.context, ...context };
111 |         if ('allowedTools' in context && context.allowedTools === undefined) {
112 |             delete (next as any).allowedTools;
113 |         }
114 |         this.context = next;
115 |     }
116 | 
117 |     static getContext(): { sessionId?: string; sessionPath?: string; allowedTools?: string[] } {
118 |         return this.context;
119 |     }
120 | 
121 |     /**
122 |      * 执行指定工具
123 |      *
124 |      * @param name - 工具名称
125 |      * @param args - 工具参数
126 |      * @returns 执行结果
127 |      * @throws 如果工具不存在或参数无效
128 |      */
129 |     static async execute(name: string, args: unknown): Promise<string> {
130 |         const tool = this.get(name);
131 |         if (!tool) {
132 |             return `Tool "${name}" not found`;
133 |         }
134 |         const allowed = this.context.allowedTools;
135 |         if (allowed && !allowed.includes(name)) {
136 |             return `Tool "${name}" is not allowed in this context`;
137 |         }
138 | 
139 |         // 验证参数
140 |         const parsed = tool.schema.safeParse(args);
141 | 
142 |         if (!parsed.success) {
143 |             return `Invalid arguments for tool "${name}": ${parsed.error.errors.map((e: { message: string }) => e.message).join(', ')}`;
144 |         }
145 | 
146 |         return await tool.execute(parsed.data);
147 |     }
148 | 
149 |     /**
150 |      * 获取工具的 schema（用于 LLM 函数调用）
151 |      *
152 |      * 返回符合 OpenAI function calling 格式：
153 |      * https://platform.openai.com/docs/guides/function-calling
154 |      *
155 |      * @returns 所有工具的 schema 数组
156 |      */
157 |     static getSchemas(): Array<{
158 |         type: 'function';
159 |         function: {
160 |             name: string;
161 |             description: string;
162 |             strict?: boolean;
163 |             parameters: Record<string, unknown>;
164 |         };
165 |     }> {
166 |         return this.getAll().map(tool => {
167 |             // 将 zod schema 转换为 JSON Schema 格式
168 |             const zodSchema = tool.schema;
169 |             const jsonSchema = this.zodToJsonSchema(zodSchema);
170 | 
171 |             return {
172 |                 type: 'function',
173 |                 function: {
174 |                     name: tool.name,
175 |                     description: tool.description,
176 |                     strict: true,
177 |                     parameters: jsonSchema,
178 |                 },
179 |             };
180 |         });
181 |     }
182 | 
183 |     /**
184 |      * 将 Zod schema 转换为 JSON Schema 格式
185 |      *
186 |      * @param schema - Zod schema
187 |      * @returns JSON Schema 对象
188 |      */
189 |     private static zodToJsonSchema(schema: any): Record<string, unknown> {
190 |         // 基础实现，处理常见类型
191 |         if (schema._def?.typeName === 'ZodObject') {
192 |             const shape = schema._def.shape();
193 |             const properties: Record<string, unknown> = {};
194 |             const required: string[] = [];
195 | 
196 |             for (const [key, value] of Object.entries(shape)) {
197 |                 const def = (value as any)._def;
198 |                 properties[key] = this.zodTypeToJsonSchema(def, key);
199 | 
200 |                 // 检查是否是可选字段
201 |                 const isOptional = (value as any)._def?.typeName === 'ZodOptional' ||
202 |                                    (value as any).isOptional?.();
203 |                 if (!isOptional) {
204 |                     required.push(key);
205 |                 }
206 |             }
207 | 
208 |             return {
209 |                 type: 'object',
210 |                 properties,
211 |                 required: required.length > 0 ? required : undefined,
212 |                 additionalProperties: false,
213 |             };
214 |         }
215 | 
216 |         return { type: 'object', properties: {}, additionalProperties: false };
217 |     }
218 | 
219 |     /**
220 |      * 将 Zod 类型转换为 JSON Schema 类型
221 |      *
222 |      * @param def - Zod 类型定义
223 |      * @param key - 字段名（用于错误信息）
224 |      * @returns JSON Schema 类型定义
225 |      */
226 |     private static zodTypeToJsonSchema(def: any, key?: string): Record<string, unknown> {
227 |         const typeName = def?.typeName;
228 | 
229 |         switch (typeName) {
230 |             case 'ZodString':
231 |                 return { type: 'string' };
232 | 
233 |             case 'ZodNumber':
234 |                 return { type: 'number' };
235 | 
236 |             case 'ZodBoolean':
237 |                 return { type: 'boolean' };
238 | 
239 |             case 'ZodNull':
240 |                 return { type: 'null' };
241 | 
242 |             case 'ZodArray':
243 |                 const itemType = this.zodTypeToJsonSchema(def.type?._def || def.type, key);
244 |                 return {
245 |                     type: 'array',
246 |                     items: itemType,
247 |                 };
248 | 
249 |             case 'ZodObject':
250 |                 return this.zodToJsonSchema({ _def: def });
251 | 
252 |             case 'ZodOptional':
253 |             case 'ZodNullable':
254 |             case 'ZodDefault':
255 |                 // innerType 是 Zod 对象，需要获取其 _def
256 |                 return this.zodTypeToJsonSchema(def.innerType._def, key);
257 | 
258 |             case 'ZodEnum':
259 |                 return {
260 |                     type: 'string',
261 |                     enum: def.values,
262 |                 };
263 | 
264 |             case 'ZodLiteral':
265 |                 return {
266 |                     type: typeof def.value,
267 |                     const: def.value,
268 |                 };
269 | 
270 |             case 'ZodUnion':
271 |             case 'ZodDiscriminatedUnion':
272 |                 return {
273 |                     anyOf: def.options?.map((opt: any) => this.zodTypeToJsonSchema(opt._def || opt)),
274 |                 };
275 | 
276 |             case 'ZodEffects':
277 |                 // 处理带描述的字段
278 |                 const innerSchema = this.zodTypeToJsonSchema(def.innerType._def, key);
279 |                 if (def.description) {
280 |                     return { ...innerSchema, description: def.description };
281 |                 }
282 |                 return innerSchema;
283 | 
284 |             default:
285 |                 // 未知类型，使用 any
286 |                 if (typeName !== undefined) {
287 |                     console.warn(`Unknown Zod type: ${typeName} for field: ${key}`);
288 |                 } else {
289 |                     console.warn(`Undefined Zod type definition for field: ${key}, def:`, def);
290 |                 }
291 |                 return {};
292 |         }
293 |     }
294 | }
295 |

--- FILE: src/tool/bash.ts ---
Range: 1 - 221

1 | /**
2 |  * Bash Tool
3 |  *
4 |  * 执行 bash 命令的工具，提供：
5 |  * - 语法验证和解析
6 |  * - 安全分析
7 |  * - 命令执行
8 |  *
9 |  * @example
10 |  * ```ts
11 |  * const tool = new BashTool();
12 |  * const result = await tool.execute({ command: 'ls -la' });
13 |  * ```
14 |  */
15 | 
16 | import { BaseTool } from './base';
17 | import { z } from 'zod';
18 | import { getBashParser } from './bash-parser';
19 | import { getPlatform,  execCommandAsync } from '../util/platform-cmd';
20 | 
21 | // =============================================================================
22 | // Schema
23 | // =============================================================================
24 | 
25 | const schema = z.object({
26 |     command: z.string().describe('The bash command to run'),
27 | });
28 | 
29 | 
30 | // =============================================================================
31 | // BashTool Class
32 | // =============================================================================
33 | 
34 | /**
35 |  * Bash 命令执行工具
36 |  *
37 |  * 在执行前对命令进行解析和安全分析
38 |  */
39 | export default class BashTool extends BaseTool<typeof schema> {
40 |     name = 'bash';
41 |     private cwd = process.cwd();
42 | 
43 |     get description(): string {
44 |         return 'Run bash commands';
45 |     }
46 | 
47 |     schema = schema;
48 | 
49 |     /** 命令执行超时时间（毫秒），默认 60 秒 */
50 |     timeout: number = 60000;
51 | 
52 |     /**
53 |      * 执行 bash 命令
54 |      *
55 |      * @param args - 包含命令的参数
56 |      * @returns 执行结果
57 |      */
58 |     async execute(args: z.infer<typeof this.schema>): Promise<string> {
59 |         const { command } = args;
60 |         const platform = getPlatform();
61 |         if (platform !== 'windows') {
62 |             const parser = await getBashParser();
63 |             const result = parser.parse(command);
64 |             if (!result.valid) {
65 |                 return 'Command not executed due to syntax error';
66 |             }
67 |         } else {
68 |             const maybeDangerous = /(^|\s)(format|shutdown|reg\s+delete|rmdir\s+\/s|rd\s+\/s|del\s+\/f)(\s|$)/i;
69 |             if (maybeDangerous.test(command)) {
70 |                 return 'Command not executed due to safety policy';
71 |             }
72 |         }
73 | 
74 |         // 执行命令
75 |         return await this.runCommand(command);
76 |     }
77 | 
78 |    
79 | 
80 |    
81 | 
82 | 
83 |     /**
84 |      * 执行 bash 命令
85 |      *
86 |      * 使用 platform-cmd 模块的跨平台执行函数
87 |      * 自动处理编码差异（Windows GBK / Unix UTF-8）
88 |      * 超时保护通过 timeout 参数传递
89 |      *
90 |      * @param command - 要执行的命令
91 |      * @returns Promise<string> - 执行结果
92 |      */
93 |     private async runCommand(command: string): Promise<string> {
94 |         const normalizedCommand = this.normalizeCommand(command);
95 |         const cdOutput = this.tryHandleCd(normalizedCommand);
96 |         if (cdOutput !== null) return this.truncateOutput( `ERROR: Command failed: ${cdOutput}`);
97 | 
98 |         const result = await execCommandAsync(normalizedCommand, {
99 |             timeout: this.timeout,
100 |             cwd: this.cwd,
101 |         });
102 | 
103 |         if (result.exitCode === 0) {
104 |             return this.truncateOutput(result.stdout || `Command exited successfully`);
105 |         } else {
106 |             // 命令失败时返回 stderr
107 |             return this.truncateOutput(result.stderr || `Command failed with exit code ${result.exitCode}`);
108 |         }
109 |     }
110 | 
111 |     private tryHandleCd(command: string): string | null {
112 |         const platform = getPlatform();
113 |         // 检测复杂命令（包含管道、重定向、命令连接符等），不做 cd 特殊处理
114 |         if (/[|;&<>]|\|\||&&/.test(command)) {
115 |             return null;
116 |         }
117 | 
118 |         const cdMatch = command.match(/^\s*cd(?:\s+\/d)?\s+(.+)\s*$/i);
119 |         if (!cdMatch) return null;
120 | 
121 |         const rawTarget = cdMatch[1]?.trim();
122 |         if (!rawTarget) return null;
123 | 
124 |         const target = rawTarget.replace(/^"(.*)"$/, '$1').replace(/^'(.*)'$/, '$1');
125 |         const resolved = platform === 'windows'
126 |             ? require('path').resolve(this.cwd, target.replace(/\//g, '\\'))
127 |             : require('path').resolve(this.cwd, target);
128 | 
129 |         this.cwd = resolved;
130 |         return this.cwd;
131 |     }
132 | 
133 |     private normalizeCommand(command: string): string {
134 |         if (getPlatform() !== 'windows') return command;
135 | 
136 |         const timeoutMatch = command.match(/^\s*timeout\s+\/t\s+(\d+)\s*$/i);
137 |         if (timeoutMatch) {
138 |             const seconds = Number(timeoutMatch[1]);
139 |             const safeSeconds = Number.isFinite(seconds) ? Math.max(0, seconds) : 0;
140 |             return `powershell -NoProfile -Command "Start-Sleep -Seconds ${safeSeconds}"`;
141 |         }
142 | 
143 |         const mkdirMatch = command.match(/^\s*mkdir\s+(-p|--parents)\s+(.+)\s*$/i);
144 |         if (mkdirMatch) {
145 |             return `mkdir ${mkdirMatch[2]}`;
146 |         }
147 | 
148 |         const { tokens, quoteTypes } = this.tokenize(command);
149 |         const normalizedTokens = tokens.map((token, i) => {
150 |             const quote = quoteTypes[i];
151 |             const original = quote ? `${quote}${token}${quote}` : token;
152 |             if (!token.includes('/')) return original;
153 |             if (token.startsWith('/')) return original;
154 |             if (token.includes('://')) return original;
155 | 
156 |             const looksLikeProjectPath =
157 |                 token.startsWith('./') ||
158 |                 token.startsWith('../') ||
159 |                 token.startsWith('src/') ||
160 |                 token.startsWith('test/') ||
161 |                 token.startsWith('__tests__/') ||
162 |                 /\.(ts|tsx|js|jsx|json|md|txt|log|env)$/i.test(token) ||
163 |                 token.includes('/src/') ||
164 |                 token.includes('/test/') ||
165 |                 token.includes('/__tests__/');
166 | 
167 |             if (!looksLikeProjectPath) return original;
168 | 
169 |             const replaced = token.replace(/\//g, '\\');
170 |             return quote ? `${quote}${replaced}${quote}` : replaced;
171 |         });
172 | 
173 |         return normalizedTokens.join(' ');
174 |     }
175 | 
176 |     private tokenize(command: string): { tokens: string[]; quoteTypes: Array<'"' | "'" | null> } {
177 |         const tokens: string[] = [];
178 |         const quoteTypes: Array<'"' | "'" | null> = [];
179 |         let current = '';
180 |         let quote: '"' | "'" | null = null;
181 | 
182 |         for (let i = 0; i < command.length; i++) {
183 |             const ch = command[i];
184 |             if ((ch === '"' || ch === "'") && quote === null) {
185 |                 quote = ch as '"' | "'";
186 |                 continue;
187 |             }
188 |             if (quote !== null && ch === quote) {
189 |                 tokens.push(current);
190 |                 quoteTypes.push(quote);
191 |                 current = '';
192 |                 quote = null;
193 |                 continue;
194 |             }
195 |             if (quote === null && /\s/.test(ch)) {
196 |                 if (current.length > 0) {
197 |                     tokens.push(current);
198 |                     quoteTypes.push(null);
199 |                     current = '';
200 |                 }
201 |                 continue;
202 |             }
203 |             current += ch;
204 |         }
205 | 
206 |         if (current.length > 0) {
207 |             tokens.push(current);
208 |             quoteTypes.push(quote);
209 |         }
210 | 
211 |         return { tokens, quoteTypes };
212 |     }
213 | 
214 |     private truncateOutput(output: string): string {
215 |         const maxChars = 12000;
216 |         if (output.length <= maxChars) return output;
217 |         return `${output.slice(0, maxChars)}\n... (truncated, ${output.length - maxChars} more chars)`;
218 |     }
219 |  
220 | }
221 |

