36 |  * 这些命令可能对系统造成破坏性影响
37 |  */
38 | const DANGEROUS_COMMANDS = new Set([
39 |     'rm',      // 删除文件/目录
40 |     'rmdir',   // 删除空目录
41 |     'mkfs',    // 创建文件系统
42 |     'dd',      // 磁盘复制/转换
43 |     'format',  // 格式化磁盘
44 |     'fdisk',   // 磁盘分区
45 |     'mkswap',  // 创建交换空间
46 |     'swapoff', // 关闭交换空间
