48 | ]);
49 | 
50 | /**
51 |  * 危险标志集合
52 |  * 用于检测 rm 等命令的危险组合
53 |  */
54 | const DANGEROUS_FLAGS = new Set(['rf', 'fr', 'f']);
55 | 
56 | /**
57 |  * 系统权限提升命令
58 |  * 这些命令需要额外权限，需要警告用户
