62 | // =============================================================================
63 | // ANSI Color Codes for Syntax Highlighting
64 | // =============================================================================
65 | 
66 | /**
67 |  * ANSI 颜色代码
68 |  * 用于终端语法高亮
69 |  */
70 | const COLORS = {
71 |     reset: '\x1b[0m',      // 重置颜色
72 |     command: '\x1b[1;36m', // 命令名 - 青色加粗
73 |     string: '\x1b[0;33m',  // 字符串 - 黄色
74 |     variable: '\x1b[1;35m',// 变量 - 紫色加粗
75 |     flag: '\x1b[0;32m',    // 标志 - 绿色
76 |     operator: '\x1b[1;31m',// 操作符 - 红色加粗
77 | };
78 | 
79 | // =============================================================================
80 | // Type Definitions
81 | // =============================================================================
82 | 
83 | /**
84 |  * 命令信息
85 |  */
86 | export interface CommandInfo {
87 |     /** 原始命令字符串 */
88 |     raw: string;
89 |     /** 命令名称（如 echo, ls） */
90 |     program?: string;
91 |     /** 命令参数列表 */
92 |     arguments: string[];
93 |     /** 是否包含管道操作 */
94 |     pipes: boolean;
95 |     /** 是否后台执行 */
96 |     background: boolean;
97 |     /** 重定向列表（如 > file, 2>&1） */
98 |     redirections: string[];
99 | }
100 | 
101 | /**
102 |  * 安全问题
103 |  */
104 | export interface SecurityIssue {
105 |     /** 严重级别 */
106 |     level: 'warning' | 'danger' | 'critical';
107 |     /** 问题描述 */
108 |     message: string;
109 |     /** 问题位置（可选） */
110 |     position?: { row: number; column: number };
111 | }
112 | 
113 | /**
114 |  * 解析结果
115 |  */
116 | export interface ParseResult {
117 |     /** 语法是否有效 */
118 |     valid: boolean;
119 |     /** 错误信息（如果语法无效） */
120 |     error?: string;
121 |     /** 命令结构信息 */
122 |     info?: CommandInfo;
123 |     /** 安全问题列表 */
124 |     security?: SecurityIssue[];
125 |     /** 带语法高亮的命令 */
126 |     highlighted?: string;
127 | }
