129 | // =============================================================================
130 | // BashParser Class
131 | // =============================================================================
132 | 
133 | /**
134 |  * Bash 命令解析器
135 |  *
136 |  * 使用 tree-sitter 进行单次 AST 遍历，同时收集：
137 |  * - 命令结构信息
138 |  * - 安全问题
139 |  * - 语法高亮片段
140 |  *
141 |  * @class BashParser
142 |  * @example
143 |  * ```ts
144 |  * const parser = new BashParser();
145 |  * await parser.init();
146 |  * const result = parser.parse('ls -la');
147 |  * ```
148 |  */
149 | export class BashParser {
150 |     /** tree-sitter 解析器实例 */
151 |     private parser: any = null;
152 |     /** 是否已完成初始化 */
153 |     private ready = false;
154 | 
155 |     /**
156 |      * 初始化解析器
157 |      * 创建 tree-sitter 实例并设置 bash 语言
158 |      */
159 |     async init(): Promise<void> {
160 |         if (this.ready) return;
161 |         this.parser = new Parser();
162 |         this.parser.setLanguage(Bash);
163 |         this.ready = true;
164 |     }
165 | 
166 |     /**
167 |      * 解析 bash 命令
168 |      *
169 |      * 执行以下操作：
170 |      * 1. 检查语法错误（ERROR 节点）
171 |      * 2. 单次遍历 AST 收集所有信息
172 |      * 3. 生成语法高亮输出
173 |      *
174 |      * @param command - 要解析的 bash 命令
175 |      * @returns 解析结果
176 |      */
177 |     parse(command: string): ParseResult {
178 |         // 空命令直接返回
179 |         if (!command || !command.trim()) return { valid: true, highlighted: '' };
180 | 
181 |         // 生成 AST
182 |         const tree = this.parser.parse(command);
183 |         const root = tree.rootNode;
184 | 
185 |         // 检查语法错误：查找 ERROR 类型节点
186 |         const errorNode = this.findError(root);
187 |         if (errorNode) {
188 |             return {
189 |                 valid: false,
190 |                 error: `Syntax error at position ${errorNode.startIndex}`,
191 |                 highlighted: command,
192 |             };
193 |         }
194 | 
195 |         // 单次遍历收集所有数据（结构、安全、高亮）
196 |         const data = this.traverse(root, command);
197 | 
198 |         return {
199 |             valid: true,
200 |             info: data.info,
201 |             security: data.security.length > 0 ? data.security : undefined,
202 |             highlighted: this.highlightFromSegments(command, data.segments),
203 |         };
204 |     }
205 | 
206 |     /**
207 |      * 在 AST 中查找错误节点
208 |      *
209 |      * 深度优先搜索，返回第一个 ERROR 类型节点
210 |      *
211 |      * @param node - 当前 AST 节点
212 |      * @returns 错误节点或 null
213 |      */
214 |     private findError(node: any): any {
215 |         if (node.type === 'ERROR') return node;
216 |         for (const child of node.children) {
217 |             const found = this.findError(child);
218 |             if (found) return found;
219 |         }
220 |         return null;
221 |     }
222 | 
223 |     /**
224 |      * 单次 AST 遍历收集所有数据
225 |      *
226 |      * 这是核心方法，一次遍历同时收集：
227 |      * - 命令结构信息（program、arguments、pipes 等）
228 |      * - 安全问题（危险命令、sudo 等）
229 |      * - 语法高亮片段（带颜色信息的位置）
230 |      *
231 |      * Tree-sitter AST 节点类型：
232 |      * - command_name: 命令名称
233 |      * - word: 普通词
234 |      * - string: 双引号字符串
235 |      * - raw_string: 单引号字符串
236 |      * - simple_expansion: $VAR 变量展开
237 |      * - expansion: ${VAR} 变量展开
238 |      * - command_substitution: $(cmd) 命令替换
239 |      * - pipeline: 管道操作
240 |      * - file_redirect: 文件重定向
241 |      * - &: 后台操作符
242 |      *
243 |      * @param root - AST 根节点
244 |      * @param source - 原始命令字符串
245 |      * @returns 包含 info、security、segments 的数据对象
246 |      */
247 |     private traverse(root: any, source: string) {
248 |         // 初始化结果收集器
249 |         const info: CommandInfo = {
250 |             raw: source,
251 |             arguments: [],
252 |             pipes: false,
253 |             background: false,
254 |             redirections: [],
255 |         };
256 |         const security: SecurityIssue[] = [];
257 |         const segments: Array<{ start: number; end: number; color: string }> = [];
258 | 
259 |         /**
260 |          * 递归访问 AST 节点
261 |          *
262 |          * @param node - 当前节点
263 |          * @param parent - 父节点（用于判断上下文）
264 |          */
265 |         const visit = (node: any, parent: any = null) => {
266 |             const type = node.type;
267 |             const text = node.text;
268 | 
269 |             // 根据节点类型收集信息
270 |             let color: string | null = null;
271 | 
272 |             switch (type) {
273 |                 case 'command_name':
274 |                     // 命令名称（如 echo, ls）
275 |                     color = COLORS.command;
276 |                     if (!info.program) info.program = text;
277 |                     break;
278 | 
279 |                 case 'string':
280 |                 case 'raw_string':
281 |                     // 字符串字面量
282 |                     color = COLORS.string;
283 |                     info.arguments.push(text);
284 |                     break;
285 | 
286 |                 case 'simple_expansion':
287 |                 case 'expansion':
288 |                 case 'command_substitution':
289 |                     // 变量展开或命令替换
290 |                     color = COLORS.variable;
291 |                     info.arguments.push(text);
292 |                     // 记录安全问题
293 |                     security.push({
294 |                         level: 'warning',
295 |                         message: type === 'command_substitution' ? 'Command contains command substitution' : 'Command contains variable expansion',
296 |                         position: { row: node.startPosition.row, column: node.startPosition.column },
297 |                     });
298 |                     break;
299 | 
300 |                 case 'word':
301 |                     // 普通词（参数等）
302 |                     // 注意：排除 command_name 的子节点（避免重复）
303 |                     if (parent?.type !== 'command_name') {
304 |                         info.arguments.push(text);
305 |                     }
306 |                     break;
307 | 
308 |                 case 'pipeline':
309 |                     // 管道操作
310 |                     info.pipes = true;
311 |                     break;
312 | 
313 |                 case '&':
314 |                     // 后台操作符
315 |                     info.background = true;
316 |                     color = COLORS.operator;
317 |                     break;
318 | 
319 |                 case '|':
320 |                     // 管道操作符
321 |                     color = COLORS.operator;
322 |                     break;
323 | 
324 |                 case 'file_redirect':
325 |                 case 'heredoc_redirect':
326 |                     // 文件重定向
327 |                     info.redirections.push(text);
328 |                     break;
329 |             }
330 | 
331 |             // 对命令名称进行安全分析
332 |             if (type === 'command_name') {
333 |                 // 提取基础命令名（去除 - 前缀和 = 赋值）
334 |                 const baseCmd = text.replace(/^-+/, '').split('=')[0];
335 | 
336 |                 // 检查权限提升命令
337 |                 if (SYSTEM_MODIFIERS.has(text)) {
338 |                     security.push({
339 |                         level: 'warning',
340 |                         message: `Command uses '${text}' - elevated privileges`,
341 |                         position: { row: node.startPosition.row, column: node.startPosition.column },
342 |                     });
343 |                 }
344 | 
345 |                 // 检查危险命令
346 |                 if (DANGEROUS_COMMANDS.has(baseCmd)) {
347 |                     security.push({
348 |                         level: 'danger',
349 |                         message: `Dangerous command detected: ${baseCmd}`,
350 |                         position: { row: node.startPosition.row, column: node.startPosition.column },
351 |                     });
352 |                 }
353 | 
354 |                 // 特殊检查：rm 命令的危险标志
355 |                 if (baseCmd === 'rm') {
356 |                     const parent = node.parent;
357 |                     if (parent) {
358 |                         // 遍历同级节点查找标志
359 |                         for (const sibling of parent.children) {
360 |                             if (sibling.type === 'word' && sibling.text.startsWith('-')) {
361 |                                 const flags = sibling.text.slice(1);
362 |                                 if ([...DANGEROUS_FLAGS].some((df) => flags.includes(df))) {
363 |                                     security.push({
364 |                                         level: 'critical',
365 |                                         message: `Command uses rm with dangerous flag: ${sibling.text}`,
366 |                                         position: { row: sibling.startPosition.row, column: sibling.startPosition.column },
367 |                                     });
368 |                                 }
369 |                             }
370 |                         }
371 |                     }
372 |                 }
373 |             }
374 | 
375 |             // 收集语法高亮片段
376 |             if (color) {
377 |                 segments.push({ start: node.startIndex, end: node.endIndex, color });
378 |             }
379 | 
380 |             // 递归访问子节点
381 |             for (const child of node.children) {
382 |                 visit(child, node);
383 |             }
384 |         };
385 | 
386 |         // 从根节点开始遍历
387 |         visit(root, null);
388 |         return { info, security, segments };
389 |     }
390 | 
391 |     /**
392 |      * 根据片段生成语法高亮字符串
393 |      *
394 |      * 将带颜色信息的片段合并为完整的 ANSI 彩色字符串
395 |      *
396 |      * @param source - 原始命令字符串
397 |      * @param segments - 高亮片段列表
398 |      * @returns 带 ANSI 颜色码的字符串
399 |      */
400 |     private highlightFromSegments(source: string, segments: Array<{ start: number; end: number; color: string }>): string {
401 |         if (!segments.length) return source;
402 | 
403 |         // 按位置排序
404 |         segments.sort((a, b) => a.start - b.start);
405 | 
406 |         let result = '';
407 |         let pos = 0;
408 | 
409 |         // 构建结果字符串
410 |         for (const seg of segments) {
411 |             // 添加高亮前的普通文本
412 |             if (seg.start > pos) result += source.slice(pos, seg.start);
413 |             // 添加带颜色的文本
414 |             result += seg.color + source.slice(seg.start, seg.end) + COLORS.reset;
415 |             pos = Math.max(pos, seg.end);
416 |         }
417 | 
418 |         // 添加剩余的普通文本
419 |         if (pos < source.length) result += source.slice(pos);
420 |         return result;
421 |     }
422 | }
423 | 
424 | // =============================================================================
425 | // Singleton Instance
426 | // =============================================================================
427 | 
428 | /**
429 |  * 单例解析器实例
430 |  * 避免重复初始化 tree-sitter（开销较大）
431 |  */
432 | let instance: BashParser | null = null;
433 | 
434 | /**
435 |  * 获取 BashParser 单例实例
436 |  *
437 |  * @returns 初始化后的解析器实例
438 |  */
439 | export async function getBashParser(): Promise<BashParser> {
440 |     if (!instance) {
441 |         instance = new BashParser();
442 |         await instance.init();
443 |     }
444 |     return instance;
445 | }
