46 |  */
47 | export class BackupManager {
48 |     private backupDir: string;
49 |     private maxBackups: number;
50 |     private enabled: boolean;
51 |     private logger: ScopedLogger;
52 |     private backupIndex: Map<string, BackupInfo[]> = new Map();
53 | 
54 |     constructor(config: BackupManagerConfig = {}) {
55 |         this.backupDir = config.backupDir || path.join(process.cwd(), '.claude', 'backups');
56 |         this.maxBackups = config.maxBackups ?? 5;
57 |         this.enabled = config.enabled ?? true;
58 |         this.logger = new ScopedLogger('BackupManager');
59 |     }
60 | 
61 |     /**
62 |      * 初始化备份管理器（创建备份目录）
63 |      */
64 |     async initialize(): Promise<void> {
65 |         if (!this.enabled) {
66 |             this.logger.debug('Backup manager is disabled');
67 |             return;
68 |         }
69 | 
70 |         try {
71 |             await fs.mkdir(this.backupDir, { recursive: true });
72 |             this.logger.debug(`Backup directory ready: ${this.backupDir}`);
73 |         } catch (error) {
74 |             this.logger.error(`Failed to create backup directory: ${error}`);
75 |             throw error;
76 |         }
77 |     }
78 | 
79 |     /**
80 |      * 备份文件
81 |      *
82 |      * @param filePath 要备份的文件路径
83 |      * @returns 备份 ID，如果备份失败返回 null
84 |      */
85 |     async backup(filePath: string): Promise<string | null> {
86 |         if (!this.enabled) {
87 |             return null;
88 |         }
89 | 
90 |         try {
91 |             // 检查文件是否存在
92 |             const stats = await fs.stat(filePath).catch(() => null);
93 |             if (!stats || !stats.isFile()) {
94 |                 this.logger.debug(`File not found, skipping backup: ${filePath}`);
95 |                 return null;
96 |             }
97 | 
98 |             // 读取文件内容
99 |             const content = await fs.readFile(filePath, 'utf-8');
100 | 
101 |             // 生成唯一备份 ID
102 |             const backupId = this.generateBackupId(filePath);
103 |             const backupPath = path.join(this.backupDir, `${backupId}.backup`);
104 | 
105 |             // 写入备份文件
106 |             await fs.writeFile(backupPath, content, 'utf-8');
107 | 
108 |             // 创建备份信息
109 |             const backupInfo: BackupInfo = {
110 |                 id: backupId,
111 |                 originalPath: filePath,
112 |                 backupPath,
113 |                 createdAt: Date.now(),
114 |                 size: stats.size,
115 |             };
116 | 
117 |             // 添加到索引
118 |             this.addToIndex(filePath, backupInfo);
119 | 
120 |             // 清理旧备份
121 |             await this.cleanOldBackups(filePath);
122 | 
123 |             this.logger.debug(`Backed up: ${filePath} -> ${backupId}`);
124 |             return backupId;
125 | 
126 |         } catch (error) {
127 |             this.logger.error(`Backup failed for ${filePath}: ${error}`);
128 |             return null;
129 |         }
130 |     }
131 | 
132 |     /**
133 |      * 恢复文件到指定备份
134 |      *
