141 |             this.logger.warn('Backup manager is disabled, cannot restore');
142 |             return false;
143 |         }
144 | 
145 |         try {
146 |             // 查找备份信息
147 |             const backups = this.backupIndex.get(filePath);
148 |             if (!backups) {
149 |                 this.logger.error(`No backups found for: ${filePath}`);
150 |                 return false;
151 |             }
152 | 
153 |             const backupInfo = backups.find(b => b.id === backupId);
154 |             if (!backupInfo) {
155 |                 this.logger.error(`Backup not found: ${backupId}`);
156 |                 return false;
157 |             }
158 | 
159 |             // 读取备份内容
160 |             const content = await fs.readFile(backupInfo.backupPath, 'utf-8');
161 | 
162 |             // 写入原始文件
163 |             await fs.writeFile(filePath, content, 'utf-8');
164 | 
165 |             this.logger.info(`Restored: ${filePath} from backup ${backupId}`);
166 |             return true;
167 | 
168 |         } catch (error) {
169 |             this.logger.error(`Restore failed for ${filePath}: ${error}`);
170 |             return false;
171 |         }
172 |     }
173 | 
174 |     /**
175 |      * 获取文件的所有备份
176 |      *
177 |      * @param filePath 文件路径
178 |      * @returns 备份信息列表（按创建时间降序）
179 |      */
