186 | 
187 |     /**
188 |      * 删除指定备份
189 |      *
190 |      * @param filePath 文件路径
191 |      * @param backupId 备份 ID
192 |      */
193 |     async deleteBackup(filePath: string, backupId: string): Promise<void> {
194 |         const backups = this.backupIndex.get(filePath);
195 |         if (!backups) return;
196 | 
197 |         const backupInfo = backups.find(b => b.id === backupId);
198 |         if (backupInfo) {
199 |             await fs.unlink(backupInfo.backupPath).catch(() => {});
200 |             this.removeFromIndex(filePath, backupId);
201 |             this.logger.debug(`Deleted backup: ${backupId}`);
202 |         }
203 |     }
204 | 
205 |     /**
206 |      * 清理文件的所有旧备份
207 |      */
208 |     async clean(filePath: string): Promise<void> {
209 |         const backups = this.backupIndex.get(filePath);
210 |         if (!backups) return;
211 | 
212 |         for (const backup of backups) {
213 |             await fs.unlink(backup.backupPath).catch(() => {});
214 |         }
215 | 
216 |         this.backupIndex.delete(filePath);
217 |         this.logger.debug(`Cleared all backups for: ${filePath}`);
218 |     }
219 | 
220 |     /**
221 |      * 清理旧备份（保留最新的 maxBackups 个）
222 |      */
223 |     private async cleanOldBackups(filePath: string): Promise<void> {
224 |         const backups = this.backupIndex.get(filePath);
225 |         if (!backups || backups.length <= this.maxBackups) {
226 |             return;
227 |         }
228 | 
229 |         // 按创建时间排序，删除最旧的
230 |         const sortedBackups = [...backups].sort((a, b) => a.createdAt - b.createdAt);
231 |         const toDelete = sortedBackups.slice(0, sortedBackups.length - this.maxBackups);
232 | 
233 |         for (const backup of toDelete) {
234 |             await fs.unlink(backup.backupPath).catch(() => {});
235 |             this.removeFromIndex(filePath, backup.id);
