248 |         return `${path.basename(filePath)}_${hash}_${Date.now()}`;
249 |     }
250 | 
251 |     /**
252 |      * 添加到索引
253 |      */
254 |     private addToIndex(filePath: string, backupInfo: BackupInfo): void {
255 |         let backups = this.backupIndex.get(filePath);
256 |         if (!backups) {
257 |             backups = [];
258 |             this.backupIndex.set(filePath, backups);
259 |         }
260 |         backups.push(backupInfo);
261 |     }
262 | 
263 |     /**
264 |      * 从索引中删除
265 |      */
266 |     private removeFromIndex(filePath: string, backupId: string): void {
267 |         const backups = this.backupIndex.get(filePath);
268 |         if (!backups) return;
269 | 
270 |         const index = backups.findIndex(b => b.id === backupId);
271 |         if (index !== -1) {
272 |             backups.splice(index, 1);
273 |         }
274 | 
275 |         if (backups.length === 0) {
276 |             this.backupIndex.delete(filePath);
277 |         }
278 |     }
279 | }
