286 |  */
287 | export function getBackupManager(config?: BackupManagerConfig): BackupManager {
288 |     if (!backupManagerInstance) {
289 |         backupManagerInstance = new BackupManager(config);
290 |     }
291 |     return backupManagerInstance;
292 | }
