226 |     try {
227 |         const result = await execaCommand(command, {
228 |             shell: true,
229 |             encoding: 'buffer' as any,
230 |             timeout: options?.timeout,
231 |             cwd: options?.cwd,
232 |         });
233 |         return {
234 |             stdout: decodeCommandOutput(result.stdout, platform),
235 |             stderr: decodeCommandOutput(result.stderr, platform),
236 |             exitCode: result.exitCode ?? 0
237 |         };
238 |     } catch (error: any) {
