1 | /**
2 |  * JSON Schema to Zod Converter
3 |  *
4 |  * 将 JSON Schema 转换为 Zod schema
5 |  * 用于将 MCP 工具的输入参数定义适配到本地的 BaseTool 接口
6 |  */
7 | 
8 | import { z } from 'zod';
9 | 
10 | // =============================================================================
11 | // JSON Schema to Zod Conversion
12 | // =============================================================================
13 | 
14 | /**
15 |  * 将 JSON Schema 转换为 Zod schema
16 |  *
17 |  * @param jsonSchema - JSON Schema 对象
18 |  * @returns Zod schema
19 |  */
20 | export function jsonSchemaToZod(jsonSchema: Record<string, unknown>): z.ZodType<any> {
21 |   return convertSchema(jsonSchema);
22 | }
23 | 
24 | /**
25 |  * 递归转换 JSON Schema 为 Zod schema
26 |  */
27 | function convertSchema(schema: Record<string, unknown>): z.ZodTypeAny {
28 |   const type = schema.type as string | string[];
29 | 
30 |   // 处理多种类型
31 |   if (Array.isArray(type)) {
32 |     // 对于多种类型，使用 z.union()
33 |     const schemas = type.map(t => convertSchema({ ...schema, type: t }));
34 |     return z.union([schemas[0], schemas[1]] as any);
35 |   }
36 | 
37 |   switch (type) {
38 |     case 'object':
39 |       return convertObjectSchema(schema);
40 | 
41 |     case 'array':
42 |       return convertArraySchema(schema);
43 | 
44 |     case 'string':
45 |       return convertStringSchema(schema);
46 | 
47 |     case 'number':
48 |     case 'integer':
49 |       return convertNumberSchema(schema);
50 | 
51 |     case 'boolean':
52 |       return z.boolean();
53 | 
54 |     case 'null':
55 |       return z.null();
56 | 
57 |     default:
58 |       // 处理引用类型 ($ref)
59 |       if ('$ref' in schema) {
60 |         throw new Error('$ref is not supported in JSON Schema conversion');
61 |       }
62 | 
63 |       // 处理 anyOf
64 |       if ('anyOf' in schema && Array.isArray(schema.anyOf)) {
65 |         const schemas = (schema.anyOf as any[]).map(s => convertSchema(s));
66 |         return z.union([schemas[0], schemas[1]] as any);
67 |       }
68 | 
69 |       // 处理 allOf
70 |       if ('allOf' in schema && Array.isArray(schema.allOf)) {
71 |         // allOf 需要合并所有 schema，这里简化处理
72 |         return convertSchema(schema.allOf[0] as any);
73 |       }
74 | 
75 |       // 处理 oneOf
76 |       if ('oneOf' in schema && Array.isArray(schema.oneOf)) {
77 |         const schemas = (schema.oneOf as any[]).map(s => convertSchema(s));
78 |         return z.discriminatedUnion('type', schemas as any);
79 |       }
80 | 
81 |       // 默认返回 any
82 |       return z.any();
83 |   }
84 | }
85 | 
86 | /**
87 |  * 转换对象类型
88 |  */
89 | function convertObjectSchema(schema: Record<string, unknown>): z.ZodTypeAny {
90 |   const properties = schema.properties as Record<string, unknown> | undefined;
91 |   const required = schema.required as string[] | undefined;
92 |   const additionalProperties = schema.additionalProperties as boolean | Record<string, unknown> | undefined;
93 | 
94 |   const shape: Record<string, z.ZodTypeAny> = {};
95 | 
96 |   if (properties) {
97 |     for (const [key, propSchema] of Object.entries(properties)) {
98 |       const propSchemaRecord = propSchema as Record<string, unknown>;
99 |       let zodSchema = convertSchema(propSchemaRecord);
100 | 
101 |       // 检查是否可选
102 |       const isRequired = required?.includes(key);
103 |       if (!isRequired) {
104 |         zodSchema = zodSchema.optional();
105 |       }
106 | 
107 |       // 处理默认值
108 |       if ('default' in propSchemaRecord) {
109 |         zodSchema = (zodSchema as any).default(propSchemaRecord.default);
110 |       }
111 | 
112 |       // 处理描述
113 |       if ('description' in propSchemaRecord) {
114 |         zodSchema = (zodSchema as any).describe(propSchemaRecord.description as string);
115 |       }
116 | 
117 |       shape[key] = zodSchema;
118 |     }
119 |   }
120 | 
121 |   let zodObject = z.object(shape);
122 | 
123 |   // 处理 additionalProperties
124 |   if (additionalProperties === false) {
125 |     zodObject = (zodObject as any).strict();
126 |   } else if (typeof additionalProperties === 'object') {
127 |     // 允许特定类型的额外属性
128 |     const additionalSchema = convertSchema(additionalProperties);
129 |     zodObject = (zodObject as any).catchall(additionalSchema);
130 |   } else if (additionalProperties === true) {
131 |     zodObject = (zodObject as any).catchall(z.any());
132 |   }
133 | 
134 |   return zodObject;
135 | }
136 | 
137 | /**
138 |  * 转换数组类型
139 |  */
140 | function convertArraySchema(schema: Record<string, unknown>): z.ZodTypeAny {
141 |   const itemsSchema = schema.items as Record<string, unknown> | undefined;
142 | 
143 |   if (!itemsSchema) {
144 |     return z.array(z.any());
145 |   }
146 | 
147 |   const itemSchema = convertSchema(itemsSchema);
148 |   return z.array(itemSchema);
149 | }
150 | 
151 | /**
152 |  * 转换字符串类型
153 |  */
154 | function convertStringSchema(schema: Record<string, unknown>): z.ZodTypeAny {
155 |   let zodString = z.string();
156 | 
157 |   // 处理枚举
158 |   if ('enum' in schema && Array.isArray(schema.enum)) {
159 |     return z.enum(schema.enum as [string, ...string[]]);
160 |   }
161 | 
162 |   // 处理格式约束
163 |   if (schema.format === 'email') {
164 |     zodString = zodString.email();
165 |   } else if (schema.format === 'uri' || schema.format === 'url') {
166 |     zodString = zodString.url();
167 |   } else if (schema.format === 'uuid') {
168 |     zodString = zodString.uuid();
169 |   }
170 | 
171 |   // 处理长度约束
172 |   if (typeof schema.minLength === 'number') {
173 |     zodString = zodString.min(schema.minLength);
174 |   }
175 |   if (typeof schema.maxLength === 'number') {
176 |     zodString = zodString.max(schema.maxLength);
177 |   }
178 | 
179 |   // 处理正则
180 |   if ('pattern' in schema && typeof schema.pattern === 'string') {
181 |     zodString = zodString.regex(new RegExp(schema.pattern));
182 |   }
183 | 
184 |   return zodString;
185 | }
186 | 
187 | /**
188 |  * 转换数字类型
189 |  */
190 | function convertNumberSchema(schema: Record<string, unknown>): z.ZodNumber {
191 |   let zodNumber = schema.type === 'integer' ? z.number().int() : z.number();
192 | 
193 |   // 处理范围约束
194 |   if (typeof schema.minimum === 'number') {
195 |     zodNumber = zodNumber.min(schema.minimum);
196 |   }
197 |   if (typeof schema.maximum === 'number') {
198 |     zodNumber = zodNumber.max(schema.maximum);
199 |   }
200 |   if (typeof schema.exclusiveMinimum === 'number') {
201 |     zodNumber = zodNumber.gt(schema.exclusiveMinimum);
202 |   }
203 |   if (typeof schema.exclusiveMaximum === 'number') {
204 |     zodNumber = zodNumber.lt(schema.exclusiveMaximum);
205 |   }
206 | 
207 |   return zodNumber;
208 | }
