25 | // =============================================================================
26 | // MCP Client
27 | // =============================================================================
28 | 
29 | /**
30 |  * MCP 客户端类
31 |  *
32 |  * 负责与 MCP 服务器通信，管理连接生命周期
33 |  */
34 | export class McpClient extends EventEmitter {
35 |   /** 服务器配置 */
36 |   private config: McpServerConfig;
37 | 
38 |   /** 子进程 */
39 |   private process: ChildProcess | null = null;
