68 |   // -------------------------------------------------------------------------
69 |   // Connection Management
70 |   // -------------------------------------------------------------------------
71 | 
72 |   /**
73 |    * 连接到 MCP 服务器
74 |    */
75 |   async connect(): Promise<void> {
76 |     if (this._state === ConnectionState.Connected || this._state === ConnectionState.Connecting) {
77 |       throw new Error(`Client is already ${this._state}`);
78 |     }
79 | 
80 |     this.setState(ConnectionState.Connecting);
81 | 
82 |     try {
83 |       console.log(`[MCP:${this.serverName}] Starting process: ${this.config.command} ${(this.config.args || []).join(' ')}`);
84 | 
85 |       // 启动服务器进程
86 |       // Windows 上需要 shell: true 来正确执行 .cmd 文件
87 |       this.process = spawn(this.config.command, this.config.args || [], {
88 |         env: { ...process.env, ...this.config.env },
89 |         stdio: ['pipe', 'pipe', 'pipe'],
90 |         shell:  process.platform === 'win32',
91 |       });
92 | 
93 |       // 设置输出处理
94 |       this.process.stdout?.on('data', (data: Buffer) => {
95 |         const output = data.toString();
96 |         console.log(`[MCP:${this.serverName}] stdout:`, output);
97 |         this.handleMessage(output);
98 |       });
99 | 
100 |       // 设置错误处理
101 |       this.process.stderr?.on('data', (data: Buffer) => {
102 |         const output = data.toString();
103 |         console.error(`[MCP:${this.serverName}] stderr:`, output);
104 |         this.emit('stderr', output);
105 |       });
106 | 
107 |       // 设置进程退出处理
108 |       this.process.on('close', (code) => {
109 |         console.log(`[MCP:${this.serverName}] Process closed with code ${code}`);
110 |         this.setState(ConnectionState.Disconnected);
111 |         this.emit('close', code);
112 |         this.rejectAllPendingRequests(new Error(`Process closed with code ${code}`));
113 |       });
114 | 
115 |       this.process.on('error', (error) => {
116 |         console.error(`[MCP:${this.serverName}] Process error:`, error.message);
117 |         this.setState(ConnectionState.Error);
118 |         this.emit('error', error);
119 |         this.rejectAllPendingRequests(error);
120 |       });
121 | 
122 |       // 初始化握手
123 |       console.log(`[MCP:${this.serverName}] Sending initialize request...`);
124 |       await this.initialize();
125 | 
126 |       this.setState(ConnectionState.Connected);
127 |       console.log(`[MCP:${this.serverName}] Connected successfully`);
128 |       this.emit('connected');
129 |     } catch (error) {
130 |       console.error(`[MCP:${this.serverName}] Connection failed:`, error);
