148 |   // -------------------------------------------------------------------------
149 |   // Protocol Methods
150 |   // -------------------------------------------------------------------------
151 | 
152 |   /**
153 |    * 初始化连接
154 |    */
155 |   private async initialize(): Promise<InitializeResult> {
