175 |   async listTools(cursor?: string): Promise<ToolsListResponse> {
176 |     const params: ToolsListRequest = cursor ? { cursor } : {};
177 |     const response = await this.sendRequest('tools/list', params as any);
178 |     const result = response.result as any;
179 |     this.cachedTools = result.tools;
180 |     return result;
181 |   }
