134 |     result = result + '"';
135 |   }
136 | 
137 |   // 尝试闭合未完成的对象/数组
138 |   while (braceDepth > 0) {
139 |     result = result + '}';
140 |     braceDepth--;
141 |   }
142 |   while (bracketDepth > 0) {
