244 |   for (let i = 0; i < lines.length; i++) {
245 |     const line = lines[i];
246 | 
247 |     if (!inString) {
248 |       result.push(line);
249 |       // 检查这一行后是否进入字符串状态
250 |       for (const char of line) {
251 |         if (escapeNext) {
252 |           escapeNext = false;
253 |           continue;
254 |         }
255 |         if (char === '\\') {
256 |           escapeNext = true;
257 |           continue;
258 |         }
259 |         if (char === '"') {
260 |           inString = !inString;
261 |         }
262 |       }
263 |     } else {
264 |       // 在字符串中，添加转义的换行
265 |       result.push('\\n' + line.trim());
266 |       // 检查这一行后是否退出字符串状态
267 |       for (const char of line) {
