5 | 
6 | export type EventHandler<T = any> = (data: T) => void | Promise<void>;
7 | export type AsyncEventHandler<T = any> = (data: T) => Promise<void>;
8 | 
9 | export interface EventMetadata {
10 |   timestamp: number;
11 |   source?: string;
12 |   correlationId?: string;
13 |   [key: string]: any;
14 | }
15 | 
16 | export interface EventContext<T = any> {
17 |   event: string;
18 |   data: T;
19 |   metadata: EventMetadata;
20 |   abort: () => void;
21 |   isAborted: boolean;
22 | }
23 | 
24 | export interface Middleware<T = any> {
25 |   (context: EventContext<T>, next: () => Promise<void>): Promise<void>;
26 | }
27 | 
28 | export interface EventBusOptions {
29 |   maxListeners?: number;
30 |   enableAsync?: boolean;
31 |   defaultTimeout?: number;
32 |   enableMetrics?: boolean;
33 | }
34 | 
35 | export interface EventMetrics {
36 |   totalEvents: number;
37 |   totalHandlers: number;
38 |   avgExecutionTime: number;
39 |   errors: number;
40 |   lastEventTime: number;
41 | }
42 | 
43 | export interface Subscription {
44 |   unsubscribe: () => void;
45 |   event: string;
46 |   handlerId: string;
47 | }
48 | 
49 | /**
50 |  * 事件总线类
51 |  */
52 | export class EventBus {
53 |   private handlers = new Map<string, Map<string, EventHandler>>();
54 |   private asyncHandlers = new Map<string, Map<string, AsyncEventHandler>>();
55 |   private middlewares = new Map<string, Middleware[]>();
56 |   private globalMiddlewares: Middleware[] = [];
57 |   private options: Required<EventBusOptions>;
58 |   private metrics = new Map<string, EventMetrics>();
