272 |     return total;
273 |   }
274 | 
275 |   /**
276 |    * 获取事件列表
277 |    */
278 |   eventNames(): string[] {
279 |     const events = new Set<string>();
280 |     for (const event of this.handlers.keys()) {
281 |       events.add(event);
282 |     }
283 |     for (const event of this.asyncHandlers.keys()) {
284 |       events.add(event);
285 |     }
286 |     for (const event of this.middlewares.keys()) {
287 |       events.add(event);
288 |     }
289 |     return Array.from(events);
290 |   }
291 | 
292 |   /**
293 |    * 获取事件指标
294 |    */
295 |   getMetrics(event?: string): EventMetrics | Map<string, EventMetrics> {
