19 |     // 短结果直接返回
20 |     const maxPreview = 200;
21 |     if (result.length <= maxPreview) {
22 |         return result;
23 |     }
24 | 
25 |     // 根据工具类型进行智能格式化
26 |     switch (toolName) {
27 |         case 'grep':
28 |             return formatSearchResults(result);
29 | 
30 |         case 'read_file':
31 |             return formatFileContent(result);
32 | 
33 |         case 'bash':
34 |             return formatBashOutput(result);
35 | 
36 |         case 'glob':
37 |             return formatGlobResults(result);
38 | 
39 |         default:
40 |             return formatGeneric(result, maxPreview);
41 |     }
42 | }
43 | 
44 | /**
45 |  * 格式化 search_code 结果
46 |  */
47 | function formatSearchResults(result: string): string {
48 |     try {
49 |         const parsed = JSON.parse(result);
50 | 
51 |         // 处理数组结果
52 |         if (Array.isArray(parsed)) {
53 |             if (parsed.length === 0) {
54 |                 return '[no matches]';
55 |             }
56 |             if (parsed.length <= 3) {
57 |                 return result; // 结果少，全部返回
58 |             }
59 | 
60 |             // 返回前3个结果 + 摘要
61 |             const preview = parsed.slice(0, 3);
62 |             return `[${parsed.length} matches]\n${JSON.stringify(preview, null, 2)}\n... (${parsed.length - 3} more matches)`;
63 |         }
64 |     } catch {
65 |         // JSON 解析失败，使用通用格式化
66 |     }
67 | 
68 |     return formatGeneric(result, 200);
69 | }
70 | 
71 | /**
72 |  * 格式化 read_file 结果
73 |  */
74 | function formatFileContent(result: string): string {
75 |     const lines = result.split('\n');
76 | 
77 |     // 提取文件路径
78 |     const headerMatch = result.match(/^--- FILE: (.+?) ---/);
79 |     const filePath = headerMatch ? headerMatch[1] : 'unknown';
80 | 
81 |     // 小于等于15行全部返回
82 |     if (lines.length <= 15) {
83 |         return result;
84 |     }
85 | 
86 |     // 返回前15行 + 摘要
87 |     return `--- FILE: ${filePath} ---\n[total: ${lines.length} lines, showing first 15]\n${lines.slice(0, 15).join('\n')}`;
88 | }
89 | 
90 | /**
91 |  * 格式化 bash 输出
92 |  */
93 | function formatBashOutput(result: string): string {
94 |     const lines = result.split('\n');
95 | 
96 |     // 小于等于5行全部返回
97 |     if (lines.length <= 5) {
98 |         return result;
99 |     }
100 | 
101 |     // 返回前5行 + 摘要
102 |     return `[${lines.length} lines]\n${lines.slice(0, 5).join('\n')}\n... (${lines.length - 5} more lines)`;
103 | }
104 | 
105 | /**
106 |  * 格式化 glob 结果
107 |  */
108 | function formatGlobResults(result: string): string {
109 |     const lines = result.split('\n').filter(l => l.trim());
110 | 
111 |     // 小于等于10个文件全部返回
112 |     if (lines.length <= 10) {
113 |         return result;
114 |     }
115 | 
116 |     // 返回前10个 + 摘要
117 |     return `[${lines.length} files]\n${lines.slice(0, 10).join('\n')}\n... (${lines.length - 10} more files)`;
118 | }
119 | 
120 | /**
121 |  * 通用格式化
122 |  */
123 | function formatGeneric(result: string, maxPreview: number): string {
124 |     return `${result.slice(0, maxPreview)}... (${result.length - maxPreview} more chars)`;
125 | }
