230 |         const sortedBackups = [...backups].sort((a, b) => a.createdAt - b.createdAt);
231 |         const toDelete = sortedBackups.slice(0, sortedBackups.length - this.maxBackups);
232 | 
233 |         for (const backup of toDelete) {
